    { const char * tb_v967 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v967; }
    { const char * tb_v968 = "// cmd.exe /c убирает первую и последнюю кавычку, если кавычек больше двух:\n"; *(const char * *)tb_grow(v_lines) = tb_v968; }
    { const char * tb_v969 = "// поэтому команда целиком берётся ещё в одни кавычки\n"; *(const char * *)tb_grow(v_lines) = tb_v969; }
    { const char * tb_v970 = "static wchar_t *tb_win_cmd(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v970; }
    { const char * tb_v971 = "    size_t n = strlen(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v971; }
    { const char * tb_v972 = "    char *q = malloc(n + 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v972; }
    { const char * tb_v973 = "    if (!q) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v973; }
    { const char * tb_v974 = "    q[0] = '\"'; memcpy(q + 1, command, n); q[n + 1] = '\"'; q[n + 2] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v974; }
    { const char * tb_v975 = "    wchar_t *w = tb_wide(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v975; }
    { const char * tb_v976 = "    free(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v976; }
    { const char * tb_v977 = "    return w;\n"; *(const char * *)tb_grow(v_lines) = tb_v977; }
    { const char * tb_v978 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v978; }
    { const char * tb_v979 = "static int tb_win_system(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v979; }
    { const char * tb_v980 = "    wchar_t *c = tb_win_cmd(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v980; }
    { const char * tb_v981 = "    int r = c ? _wsystem(c) : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v981; }
    { const char * tb_v982 = "    free(c);\n"; *(const char * *)tb_grow(v_lines) = tb_v982; }
    { const char * tb_v983 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v983; }
    { const char * tb_v984 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v984; }
    { const char * tb_v985 = "static FILE *tb_win_popen(const char *command, const char *mode) {\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
    { const char * tb_v986 = "    wchar_t *c = tb_win_cmd(command), *m = tb_wide(mode);\n"; *(const char * *)tb_grow(v_lines) = tb_v986; }
    { const char * tb_v987 = "    FILE *f = c && m ? _wpopen(c, m) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v987; }
    { const char * tb_v988 = "    free(c); free(m);\n"; *(const char * *)tb_grow(v_lines) = tb_v988; }
    { const char * tb_v989 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v989; }
    { const char * tb_v990 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v990; }
    { const char * tb_v991 = "// папка: _wopendir / _wreaddir, имена — в UTF-8\n"; *(const char * *)tb_grow(v_lines) = tb_v991; }
    { const char * tb_v992 = "struct tb_win_dirent { char d_name[MAX_PATH * 4]; };\n"; *(const char * *)tb_grow(v_lines) = tb_v992; }
    { const char * tb_v993 = "typedef struct { _WDIR *d; struct tb_win_dirent e; } tb_win_dir;\n"; *(const char * *)tb_grow(v_lines) = tb_v993; }
    { const char * tb_v994 = "static tb_win_dir *tb_win_opendir(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v994; }
    { const char * tb_v995 = "    wchar_t *p = tb_wide(path);\n"; *(const char * *)tb_grow(v_lines) = tb_v995; }
    { const char * tb_v996 = "    _WDIR *d = p ? _wopendir(p) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v996; }
