    { const char * tb_v2271 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2271; }
    { const char * tb_v2272 = "static const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2272; }
    { const char * tb_v2273 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2273; }
    { const char * tb_v2274 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2274; }
    { const char * tb_v2275 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v2275; }
