    { const char * tb_v2277 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v2277; }
    { const char * tb_v2278 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2278; }
    { const char * tb_v2279 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v2279; }
    { const char * tb_v2280 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2280; }
    { const char * tb_v2281 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2281; }
    { const char * tb_v2282 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v2282; }
    { const char * tb_v2283 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v2283; }
    { const char * tb_v2284 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2284; }
