    { const char * tb_v2288 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2288; }
    { const char * tb_v2289 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2289; }
