    { const char * tb_v2478 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2478; }
    { const char * tb_v2479 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2479; }
    { const char * tb_v2480 = "    if (b < a) { long long t = a; a = b; b = t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2480; }
