    { const char * tb_v2510 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2510; }
    { const char * tb_v2511 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v2511; }
    { const char * tb_v2512 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v2512; }
    { const char * tb_v2513 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v2513; }
    { const char * tb_v2514 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v2514; }
    { const char * tb_v2515 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2515; }
    { const char * tb_v2516 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v2516; }
