    { const char * tb_v2520 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2520; }
    { const char * tb_v2521 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2521; }
    { const char * tb_v2522 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2522; }
