    { const char * tb_v2542 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2542; }
    { const char * tb_v2543 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2543; }
    { const char * tb_v2544 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2544; }
    { const char * tb_v2545 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2545; }
    { const char * tb_v2546 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2546; }
    { const char * tb_v2547 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2547; }
    { const char * tb_v2548 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2548; }
