    { const char * tb_v2584 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v2584; }
    { const char * tb_v2585 = "static void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2585; }
    { const char * tb_v2586 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2586; }
    { const char * tb_v2587 = "    while (n < d->keys->len * 2 + 2) n *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2587; }
