    { const char * tb_v2589 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2589; }
    { const char * tb_v2590 = "// mode 2: таблица pos на ключи base .. base+npos-1\n"; *(const char * *)tb_grow(v_lines) = tb_v2590; }
    { const char * tb_v2591 = "static void tb_dto_pos(tb_dict *d, long long npos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2591; }
    { const char * tb_v2592 = "    long long *p = tb_dalloc(d, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2592; }
