    { const char * tb_v2665 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2665; }
    { const char * tb_v2666 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2666; }
    { const char * tb_v2667 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2667; }
