    { const char * tb_v2707 = "// элемент списка заранее (prefetch за пределами списка ничего не ломает)\n"; *(const char * *)tb_grow(v_lines) = tb_v2707; }
    { const char * tb_v2708 = "static inline void tb_lpre(tb_list *l, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2708; }
    { const char * tb_v2709 = "    __builtin_prefetch(l->data + i * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2709; }
    { const char * tb_v2710 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2710; }
    { const char * tb_v2711 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2711; }
