    { const char * tb_v2734 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2734; }
    { const char * tb_v2735 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2735; }
    { const char * tb_v2736 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v2736; }
