    { const char * tb_v2740 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2740; }
    { const char * tb_v2741 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2741; }
