    { const char * tb_v2747 = "static int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2747; }
    { const char * tb_v2748 = "static void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2748; }
    { const char * tb_v2749 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2749; }
    { const char * tb_v2750 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2750; }
    { const char * tb_v2751 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v2751; }
    { const char * tb_v2752 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2752; }
    { const char * tb_v2753 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v2753; }
    { const char * tb_v2754 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2754; }
    { const char * tb_v2755 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2755; }
    { const char * tb_v2756 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2756; }
    { const char * tb_v2757 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2757; }
    { const char * tb_v2758 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v2758; }
    { const char * tb_v2759 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2759; }
    { const char * tb_v2760 = "static tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2760; }
    { const char * tb_v2761 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2761; }
    { const char * tb_v2762 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2762; }
    { const char * tb_v2763 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2763; }
    { const char * tb_v2764 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2764; }
    { const char * tb_v2765 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2765; }
    { const char * tb_v2766 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2766; }
    { const char * tb_v2767 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2767; }
    { const char * tb_v2768 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2768; }
    { const char * tb_v2769 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2769; }
    { const char * tb_v2770 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v2770; }
    { const char * tb_v2771 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v2771; }
    { const char * tb_v2772 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v2772; }
    { const char * tb_v2773 = "static pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2773; }
    { const char * tb_v2774 = "static int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2774; }
    { const char * tb_v2775 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v2775; }
    { const char * tb_v2776 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v2776; }
    { const char * tb_v2777 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
    { const char * tb_v2779 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2779; }
    { const char * tb_v2780 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2780; }
    { const char * tb_v2781 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2781; }
    { const char * tb_v2782 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2782; }
    { const char * tb_v2783 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2783; }
    { const char * tb_v2784 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2784; }
    { const char * tb_v2785 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2785; }
    { const char * tb_v2786 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2786; }
    { const char * tb_v2787 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2787; }
    { const char * tb_v2788 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2788; }
    { const char * tb_v2789 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2789; }
    { const char * tb_v2790 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2790; }
    { const char * tb_v2791 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2791; }
    { const char * tb_v2792 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2792; }
    { const char * tb_v2793 = "static pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2793; }
    { const char * tb_v2794 = "static pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2794; }
    { const char * tb_v2795 = "static int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2795; }
    { const char * tb_v2796 = "static volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2796; }
    { const char * tb_v2797 = "static volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2797; }
    { const char * tb_v2798 = "static void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2798; }
    { const char * tb_v2799 = "static void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2799; }
    { const char * tb_v2800 = "static void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2800; }
    { const char * tb_v2801 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2801; }
    { const char * tb_v2802 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v2802; }
    { const char * tb_v2803 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2803; }
    { const char * tb_v2804 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2804; }
    { const char * tb_v2805 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2805; }
    { const char * tb_v2806 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v2806; }
    { const char * tb_v2807 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2807; }
    { const char * tb_v2808 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2808; }
    { const char * tb_v2809 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2809; }
    { const char * tb_v2810 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2810; }
    { const char * tb_v2811 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v2811; }
    { const char * tb_v2812 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v2812; }
    { const char * tb_v2813 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v2813; }
    { const char * tb_v2814 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v2814; }
    { const char * tb_v2815 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2815; }
    { const char * tb_v2816 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2816; }
    { const char * tb_v2817 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2817; }
    { const char * tb_v2818 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2818; }
    { const char * tb_v2819 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2819; }
    { const char * tb_v2820 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2820; }
    { const char * tb_v2821 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v2821; }
    { const char * tb_v2822 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2822; }
    { const char * tb_v2823 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2823; }
    { const char * tb_v2824 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
    { const char * tb_v2826 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2826; }
    { const char * tb_v2827 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2827; }
    { const char * tb_v2828 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2828; }
    { const char * tb_v2829 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2829; }
    { const char * tb_v2830 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2830; }
    { const char * tb_v2831 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2831; }
    { const char * tb_v2832 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v2832; }
    { const char * tb_v2833 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2833; }
    { const char * tb_v2834 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2834; }
    { const char * tb_v2835 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2835; }
    { const char * tb_v2836 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2836; }
    { const char * tb_v2837 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2837; }
    { const char * tb_v2838 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2838; }
    { const char * tb_v2839 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2839; }
    { const char * tb_v2840 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2840; }
    { const char * tb_v2841 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2841; }
    { const char * tb_v2842 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v2842; }
    { const char * tb_v2843 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2843; }
    { const char * tb_v2844 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v2844; }
    { const char * tb_v2845 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2845; }
    { const char * tb_v2846 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2846; }
    { const char * tb_v2847 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2847; }
    { const char * tb_v2848 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2848; }
    { const char * tb_v2849 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2849; }
    { const char * tb_v2850 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v2850; }
    { const char * tb_v2851 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2851; }
    { const char * tb_v2852 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v2852; }
    { const char * tb_v2853 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2853; }
    { const char * tb_v2854 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2854; }
    { const char * tb_v2855 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2855; }
    { const char * tb_v2856 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2856; }
    { const char * tb_v2857 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2857; }
    { const char * tb_v2858 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2858; }
    { const char * tb_v2859 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2859; }
    { const char * tb_v2860 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2860; }
    { const char * tb_v2861 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2861; }
    { const char * tb_v2862 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2862; }
    { const char * tb_v2863 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2863; }
    { const char * tb_v2864 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2864; }
    { const char * tb_v2865 = "static long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2865; }
    { const char * tb_v2866 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v2866; }
    { const char * tb_v2867 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v2867; }
    { const char * tb_v2868 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2868; }
    { const char * tb_v2869 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2869; }
    { const char * tb_v2870 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2870; }
    { const char * tb_v2871 = "static inline long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
    { const char * tb_v2872 = "static inline long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2872; }
