    { const char * tb_v3438 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v3438; }
    { const char * tb_v3439 = "static void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3439; }
    { const char * tb_v3440 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3440; }
    { const char * tb_v3441 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3441; }
    { const char * tb_v3442 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v3442; }
