    { const char * tb_v3449 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3449; }
    { const char * tb_v3450 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v3450; }
    { const char * tb_v3451 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v3451; }
    { const char * tb_v3452 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3452; }
    { const char * tb_v3453 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3453; }
    { const char * tb_v3454 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v3454; }
    { const char * tb_v3455 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v3455; }
